coding.starterCode:
function transform(value: string | null | undefined, limit: number): string {
  return value!.slice(0, limit) + "…";
}

coding.referenceSolution:
function transform(value: string | null | undefined, limit: number): string {
  if (value == null) return "";
  return value.length <= limit ? value : value.slice(0, limit) + "…";
}

coding.starterCode:
function initials(name: string): string {
  return name.split(" ").map((w) => w[0]).join("");
}

coding.referenceSolution:
function initials(name: string): string {
  return name
    .trim()
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((w) => w[0].toUpperCase())
    .join("");
}

coding.starterCode:
function required(value: unknown): { required: boolean } | null {
  return { required: !value };
}

coding.referenceSolution:
function required(value: unknown): { required: true } | null {
  const empty = value === null || value === undefined || value === "" || (Array.isArray(value) && value.length === 0);
  return empty ? { required: true } : null;
}

