}

coding.starterCode:
function buildUrl(commands: (string | number)[], queryParams: Record<string, string | number | null | undefined>): string {
  const path = commands.join("/");
  const qs = Object.entries(queryParams).map(([k, v]) => `${k}=${v}`).join("&");
  return path + "?" + qs;
}

coding.referenceSolution:
function buildUrl(commands: (string | number)[], queryParams: Record<string, string | number | null | undefined>): string {
  const path = "/" + commands.map(String).map((c) => c.replace(/^\/+|\/+$/g, "")).filter(Boolean).join("/");
  const qs = Object.entries(queryParams)
    .filter(([, v]) => v !== null && v !== undefined)
    .map(([k, v]) => `${k}=${encodeURIComponent(String(v))}`)
    .join("&");
  return qs ? `${path}?${qs}` : path;
}

