}

coding.referenceSolution:
function switchMapResults(requests) {
  return requests
    .filter((r, i) => i === requests.length - 1 || r.doneAt <= requests[i + 1].sentAt)
    .sort((a, b) => a.doneAt - b.doneAt)
    .map((r) => r.q);
}

coding.starterCode:
function combineLatest(events) {
  let a, b;
  return events.map((e) => {
    if (e.src === "a") a = e.v;
    else b = e.v;
    return [a, b];
  });
}

coding.referenceSolution:
function combineLatest(events) {
  let a, b;
  let hasA = false, hasB = false;
  const out = [];
  for (const e of events) {
    if (e.src === "a") { a = e.v; hasA = true; }
    else { b = e.v; hasB = true; }
    if (hasA && hasB) out.push([a, b]);
  }
  return out;
}

