coding.starterCode:
function searchTerms(keys) {
  return keys.map((k) => k.value.trim()).filter((v) => v.length >= 2);
}

coding.referenceSolution:
function searchTerms(keys) {
  const out = [];
  keys.forEach((k, i) => {
    const next = keys[i + 1];
    if (next && next.t - k.t < 300) return;
    const v = k.value.trim();
    if (v.length < 2) return;
    if (out.length && out[out.length - 1] === v) return;
    out.push(v);
  });
  return out;
}

coding.starterCode:
type Item = { id: string; name: string; [k: string]: unknown };
type State = { ids: string[]; entities: Record<string, Item> };

function upsertMany(state: State, items: Item[]): State {
  const entities = { ...state.entities };
  const ids = [...state.ids];
  for (const item of items) {
    entities[item.id] = item;
    ids.push(item.id);
  }
  return { ids, entities };
}

coding.referenceSolution:
type Item = { id: string; name: string; [k: string]: unknown };
type State = { ids: string[]; entities: Record<string, Item> };

function upsertMany(state: State, items: Item[]): State {
  const entities = { ...state.entities };
  for (const item of items) {
    entities[item.id] = entities[item.id] ? { ...entities[item.id], ...item } : item;
  }
  const ids = Object.keys(entities).sort((a, b) => entities[a].name.localeCompare(entities[b].name));
  return { ids, entities };
}

function exhaustClicks(clicks, duration) {
  const out = [];
  let busyUntil = -Infinity;
  for (const t of clicks) {
    if (t >= busyUntil) {
      out.push(t);
      busyUntil = t + duration;
    }
  }
  return out;
}

coding.starterCode:
function authHeaders(url: string, token: string, apiOrigin: string): Record<string, string> {
  return { Authorization: `Bearer ${token}` };
}

coding.referenceSolution:
function authHeaders(url: string, token: string, apiOrigin: string): Record<string, string> {
  if (!token) return {};
  let ours = false;
  if (url.startsWith("/api/")) ours = true;
  else if (/^https?:\/\//i.test(url)) ours = new URL(url).origin === apiOrigin;
  return ours ? { Authorization: `Bearer ${token}` } : {};
}

coding.starterCode:
function retryDelays(statuses, maxRetries, baseMs) {
  return statuses.slice(0, maxRetries).map((_, n) => baseMs * 2 ** n);
}

coding.referenceSolution:
function retryDelays(statuses, maxRetries, baseMs) {
  const delays = [];
  for (const s of statuses) {
    const retryable = s === 0 || (s >= 500 && s <= 599);
    if (!retryable || delays.length >= maxRetries) break;
    delays.push(baseMs * 2 ** delays.length);
  }
  return delays;
}
